import{z as n,x as d,o as e,c as A,q as r,j as i,D as o,d as t,s as l,S as D,b as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"DoH / DoT","description":"","frontmatter":{"title":"DoH / DoT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/doh-dot.md","filePath":"cs/doh-dot.md","lastUpdated":1791063341000}'),T={name:"cs/doh-dot.md"};function p(S,a,h,B,c,C){const E=d("Mermaid");return e(),A("div",null,[a[2]||(a[2]=r('<h1 id="doh-dot" tabindex="-1">DoH / DoT <a class="header-anchor" href="#doh-dot" aria-label="Permalink to &quot;DoH / DoT&quot;">​</a></h1><div class="epigraph"><p>DoT 在 TLS 上跑 DNS 报文，DoH 把查询放进 HTTPS；机密对路径上的观察者隐藏 QNAME，把信任挪到解析器运营方。</p><footer>—— 据 RFC 7858 DoT；RFC 8484 DoH 整理</footer></div><p><a href="/cs/dnssec">DNSSEC</a> 不加密。<a href="/cs/http-tls-entry">TLS 入口</a> 已有信道。<a href="/cs/dnssec">上一课</a> 留下嗅探。缺口是 <strong>DoT/DoH</strong>：端口 853 vs 443、与企业过滤的张力。本课不把 GeoDNS 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>咖啡馆 Wi‑Fi 看见你查询。DoT：TCP/TLS 853。DoH：GET/POST <code>application/dns-message</code>，混在 Web 流量里。客户端要钉解析器证书（或系统配置），否则只是换中间人。DNSSEC 仍可在隧道里验数据。与 QUIC：DoQ 点名。Cookie 与 DoH 共享 HTTPS 栈，缓存层次不同。</p><p>不要把 DoH 写成 DNSSEC 的替代。</p><p><span class="marginnote">RFC 8484。Split DNS 企业场景会冲突。本课不站队政策。</span></p><h3 id="机密化-stub–递归" tabindex="-1">机密化 stub–递归 <a class="header-anchor" href="#机密化-stub–递归" aria-label="Permalink to &quot;机密化 stub–递归&quot;">​</a></h3><p>信任挪到解析器运营方。DNSSEC 仍验数据。企业过滤与 443 混叠是政策张力。不是 DNSSEC 替代。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：53 明文 / DoT / DoH。画：stub → TLS → 解析器。与 Happy Eyeballs 同类：发现与回退。</p>',11)),(e(),i(D,null,{default:o(()=>[l(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUB%5B%22%E5%AD%98%E6%A0%B9%22%5D%20--%3E%20DOT%5B%22TLS%20853%22%5D%0A%20%20STUB%20--%3E%20DOH%5B%22HTTPS%20443%22%5D%0A%20%20AUTH%5B%22%E4%BB%8D%E9%97%AE%E6%9D%83%E5%A8%81%2053%20%E6%88%96%E5%90%8C%E6%A0%B7%E5%8A%A0%E5%AF%86%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E5%99%A8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"递归器到权威仍常明文，观察点上移到大型解析器。TTL 缓存仍在递归器。H3 可载 DoH。中间企业防火墙看见 443 无法按域过滤 DNS，这是设计后果。RTT：多一次 TLS，连接复用摊销，像 HTTP 持久。",-1)),(e(),i(D,null,{default:o(()=>[l(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%AD%98%E6%A0%B9%2F%E6%B5%8F%E8%A7%88%E5%99%A8%22%5D%20--%3E%7C%22DoH%2FDoT%20%E5%8A%A0%E5%AF%86%E6%AE%B5%EF%BC%9A%E6%9C%AC%E5%9C%B0%20Wi-Fi%20%E5%8F%AA%E8%A7%81%E5%AF%86%E6%96%87%22%7C%20B%5B%22%E9%80%92%E5%BD%92%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%8E%E6%96%87%2053%20%E6%AE%B5%EF%BC%9A%E8%B7%AF%E5%BE%84%E4%B8%8A%E4%BB%8D%E5%8F%AF%E8%AF%BB%22%7C%20C%5B%22%E6%9D%83%E5%A8%81%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%0A%20%20B%20--%3E%20D%5B%22%E8%A7%A3%E6%9E%90%E5%99%A8%E8%BF%90%E8%90%A5%E6%96%B9%EF%BC%9A%E5%8F%AF%E8%A7%81%E6%9D%A5%E6%BA%90%20IP%20%E4%B8%8E%E5%85%A8%E9%83%A8%20QNAME%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">观察点移动：加密 stub–递归后，咖啡馆 Wi-Fi 看不到了，但解析器运营方看得更全——它同时知道你是谁（来源 IP）和你问了什么（QNAME）。加密没有消灭可见性，只是把可见性集中到了一个位置。</span></p><p><span class="marginnote">初学者容易以为上了 DoH 就能防 DNS 劫持。实际上 DoH 只保证「报文在传输途中不被偷看和篡改」；解析器返回的数据是不是真的，仍要靠 DNSSEC 验签。两者是互补关系，不是替代。</span></p><p>SYN 泛洪变成 HTTPS 泛洪，对象换层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Oblivious DoH 的全部。GeoDNS 是下一课。后课默认：DoT/DoH 机密化 stub–递归；信任解析器。</p><p>把所有设备钉同一公共 DoH，等于把元数据集中。</p><p><span class="marginnote">数字实例：明文 DNS 一次查询约 1 个 RTT；DoT/DoH 首次查询要多付一次 TLS 握手（TCP 加 TLS 大约 2-3 个 RTT），但连接复用后，后续上千次查询摊销下来每次只多微秒级开销——和 HTTP 持久连接是一个道理。</span></p><p>下一课<a href="/cs/geodns">GeoDNS</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DoT/DoH 加密查询路径。</li><li>DNSSEC 仍验数据。</li><li>信任与可见性从路径挪到解析器。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7858；RFC 8484。</li></ul>',10))])}const H=n(T,[["render",p]]);export{u as __pageData,H as default};
